local TweenService = game:GetService("TweenService")
local module = {}

local gui:ScreenGui = script.alert.NezaAlertGui
local playerGui = game.Players.LocalPlayer and game.Players.LocalPlayer:WaitForChild("PlayerGui")
if not playerGui then
    return
end
gui.Parent = playerGui
local canvasList = gui.CanvasGroup

module.AlertType = {
    Warn = "Warn",
    Error = "Error",
    Success = "Success",
    Info = "Info",
    Awesome = "Awesome",
}

local layoutOrder = 10000

local function tweenProgress(progress: Frame, duration: number, callback: () -> ())
    local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Linear)
    local tween = TweenService:Create(progress, tweenInfo, {Size = UDim2.fromScale(0, 0.07)})
    tween:Play()
    tween.Completed:Once(function()
        tween:Destroy()
        if callback then
            callback()
        end
    end)
end

module.ShowAlert = function(alertType: string, message: string)
    local alert = script.alert:FindFirstChild(alertType):Clone()
    alert.Parent = canvasList
    alert.Content.Title.Text = message
    alert.LayoutOrder = layoutOrder
    layoutOrder -= 1
    alert.UIScale.Scale = 0

    alert.MouseButton1Click:Once(function()
        TweenService:Create(alert.Content.UIScale, TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 0}):Play()
        game.Debris:AddItem(alert, 0.5)
    end)

    TweenService:Create(alert.UIScale, TweenInfo.new(0.5, Enum.EasingStyle.Back), {Scale = 1}):Play()
    game.Debris:AddItem(alert, 3.5)
    tweenProgress(alert.Content.CanvasGroup.Pro, 3, function()
        if alert:IsDescendantOf(canvasList) then
            TweenService:Create(alert.Content.UIScale, TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.In), {Scale = 0}):Play()
        end
    end)
end

module.Warn = function(message: string)
    module.ShowAlert(module.AlertType.Warn, message)
end

module.Error = function(message: string)
    module.ShowAlert(module.AlertType.Error, message)
end

module.Success = function(message: string)
    module.ShowAlert(module.AlertType.Success, message)
end

module.Info = function(message: string)
    module.ShowAlert(module.AlertType.Info, message)
end

return module
